<?php $pageHeading=$album['title'] ?? ''; include __DIR__.'/banner.php'; ?>
<section class="next-shell next-archive"><a class="next-back" href="/galeri"><?= e(PublicTheme::text($settings,'gallery')) ?></a><?php if (!empty($album['description'])): ?><p class="next-deck"><?= e($album['description']) ?></p><?php endif; ?><div class="next-media-grid">
<?php foreach ($items ?? [] as $item): ?><figure class="next-media-item"><?php if (($item['type'] ?? 'image') === 'image' && !empty($item['file_path'])): ?><a href="/storage/<?= e($item['file_path']) ?>" target="_blank" rel="noopener noreferrer"><img src="/storage/<?= e($item['file_path']) ?>" alt="<?= e($item['title'] ?? '') ?>" loading="lazy" decoding="async"></a><?php else: ?><?php $url=Security::safeLinkUrl((string) ($item['video_url'] ?? $item['youtube_url'] ?? '')); $source=$item['video_source'] ?? ''; $videoId=$item['video_id'] ?? $item['youtube_video_id'] ?? ''; ?><?php if (($source==='youtube' || !empty($item['youtube_video_id'])) && preg_match('/^[a-zA-Z0-9_-]{11}$/D',(string)$videoId)): ?><iframe src="https://www.youtube.com/embed/<?= e($videoId) ?>" title="<?= e($item['title'] ?? '') ?>" loading="lazy" allowfullscreen></iframe><?php elseif ($source==='direct' && $url!==''): ?><video src="<?= e($url) ?>" controls preload="metadata"></video><?php elseif ($url!==''): ?><a class="next-video-link" href="<?= e($url) ?>" target="_blank" rel="noopener noreferrer"><?= e($item['title'] ?? $url) ?> ↗</a><?php endif; ?><?php endif; ?><figcaption><strong><?= e($item['title'] ?? '') ?></strong><p><?= e($item['description'] ?? '') ?></p></figcaption></figure><?php endforeach; ?>
</div><?php if (empty($items)): ?><p class="next-empty"><?= e(PublicTheme::text($settings,'empty')) ?></p><?php endif; ?></section>
